uid_t r_id, e_id, s_id;
int ret;

// Basic ID retrieval
r_id = getuid();   // Real UID
e_id = geteuid();  // Effective UID

// Extended retrieval (Real, Effective, Saved Set)
ret = getresuid(&r_id, &e_id, &s_id);

// Setting RUID, EUID, SUID simultaneously (if unprivileged, only sets EUID)
ret = setuid(1000);

// Setting Real and Effective IDs distinctly
// Use -1 to keep the current ID
ret = setreuid(-1, 1001); // Keep RUID, set EUID to 1001
